import json
raw = '{"action":"lookup_lesson","slug":"vectors-and-similarity"}'
proposal = json.loads(raw)
known = {"vectors-and-similarity": "Vectors and similarity"}
def dispatch(value):
    if not isinstance(value, dict) or set(value) != {"action", "slug"}:
        raise ValueError("Unexpected schema")
    if value["action"] != "lookup_lesson" or not isinstance(value["slug"], str):
        raise ValueError("Unsupported action")
    return known.get(value["slug"], "Not found")
print(dispatch(proposal))
